// What a little 3D landmark model's card says (components/countryMap/LandmarkModelCard.jsx;
// 24 Nov 2026, the user's wish: press a model on a country's map to read about it). A model
// shows one thing (Big Ben, the Arc de Triomphe) of a landmark we know (its `landmark`, the
// landmarks reply's `wikidataId`): Westminster Palace and Abbey, Paris's Banks of the Seine.
// About its place: utils/map/landmarkModelFacts.js (generated by images/src/tools/model-facts.mjs).

const WIKIDATA_ITEM = /^Q\d+$/;
const FEET_PER_METRE = 3.28084;

/** The landmark a model belongs to, from the landmarks reply, or null (not loaded, or none). */
export const landmarkOfModel = (landmarks, model) =>
  (model?.landmark && landmarks?.find((landmark) => landmark.wikidataId === model.landmark)) || null;

/** The landmark's name when the model shows only part of it ("Part of …"), else null. */
export const partOfName = (model, landmark) => (landmark && landmark.name !== model.name ? landmark.name : null);

/**
 * "Read about it on Wikipedia" when there's no article of its own: Wikidata's jump to the item's
 * English Wikipedia article (its item page when there's none), or null for anything that isn't
 * an item's id.
 */
export const wikipediaUrlFor = (wikidataId) =>
  WIKIDATA_ITEM.test(wikidataId || '') ? `https://www.wikidata.org/wiki/Special:GoToLinkedPage/enwiki/${wikidataId}` : null;

/** An English Wikipedia article's address from its title. */
export const articleUrl = (title) => `https://en.wikipedia.org/wiki/${encodeURIComponent(String(title).replace(/ /g, '_'))}`;

/** A length in metres as the card says it, with feet: "96 m (315 ft)". */
export const metresWords = (m) =>
  `${Number(m).toLocaleString('en-GB')} m (${Math.round(m * FEET_PER_METRE).toLocaleString('en-GB')} ft)`;

/** Where it stands: "Westminster, United Kingdom", or the country alone. */
export const whereWords = (stateName, countryName) => [stateName, countryName].filter(Boolean).join(', ');

/**
 * The card's facts, in order, as `[label, words]`: where it stands, the landmark it's part of
 * (when that isn't a World Heritage Site, whose row names it), when it dates from, its height
 * (else the ground's elevation), its architects, and the World Heritage Site.
 */
export function modelFactRows({ model, facts, stateName, countryName, landmark }) {
  const rows = [];
  const where = whereWords(stateName, countryName);
  if (where) rows.push(['Where', where]);
  const partOf = model ? partOfName(model, landmark) : null;
  if (partOf && !landmark?.isUnesco) rows.push(['Part of', partOf]);
  // Wikidata's inception: often when building began (Big Ben's 1843, finished in 1859)
  if (facts?.built) rows.push(['Dates from', facts.built]);
  if (facts?.height) rows.push(['Height', metresWords(facts.height)]);
  else if (facts?.elevation) rows.push(['Elevation', metresWords(facts.elevation)]);
  if (facts?.architects?.length) rows.push([facts.architects.length === 1 ? 'Architect' : 'Architects', facts.architects.join(', ')]);
  if (landmark?.isUnesco) rows.push(['World Heritage', landmark.name]);
  return rows;
}
